/**
 * ==============================================================================================
 * HÀM CẬP NHẬT TRỰC TIẾP DỮ LIỆU CHẤM CÔNG & TĂNG CA CHUẨN XÁC 100% (THEO QUẢN ĐỐC GCCK 2026)
 * - Xóa sạch 100% các chuỗi mã máy cũ (M-FUJI-01+4, M-OKK1-01+4...)
 * - Đưa toàn bộ về ký hiệu CA CHUẨN: C1, C1+2, C3, C3+2, CN
 * - Tăng ca ngày thường chuẩn xác: 2 TIẾNG (2.0h), không còn số 4 tiếng
 * - Phụ cấp ăn ca khớp 100% theo bảng web: 15.000 đ, 30.000 đ, 10.000 đ
 * - Tổng tháng 9: đúng 128 công, 44 ca 3, 150h TC x1.5, 191h TC x2, 2.175.000 đ ăn ca
 * ==============================================================================================
 */

function capNhatChamCongChuan2Tieng() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var ws = ss.getSheetByName("07_Cham_Cong_Tang_Ca");
  if (!ws) {
    SpreadsheetApp.getUi().alert("Không tìm thấy sheet '07_Cham_Cong_Tang_Ca'!");
    return;
  }

  // 1. Lấy dữ liệu 361 bản ghi chuẩn xác 100% (T8: 210 dòng, T9: 151 dòng)
  var cleanRows = taoDanhSachBanGhiChamCongChuan();

  // 2. Xóa sạch dữ liệu cũ từ dòng 4 trở đi để loại bỏ toàn bộ dữ liệu máy cũ
  var lastRow = ws.getLastRow();
  if (lastRow >= 4) {
    ws.getRange(4, 1, lastRow - 3, 24).clearContent();
  }

  // 3. Ghi đè toàn bộ mảng dữ liệu chuẩn sạch vào Google Sheets
  var numRows = cleanRows.length;
  ws.getRange(4, 1, numRows, 24).setValues(cleanRows);

  // 4. Kẻ viền và định dạng căn lề chuẩn chuyên nghiệp
  var thinBorder = "#cbd5e1";
  ws.getRange(4, 1, numRows, 24).setBorder(true, true, true, true, true, true, thinBorder, SpreadsheetApp.BorderStyle.SOLID);
  
  for (var i = 0; i < numRows; i++) {
    var r = i + 4;
    var bg = (r % 2 === 1) ? "#ffffff" : "#f8fafc";
    ws.getRange(r, 1, 1, 24).setBackground(bg).setFontFamily("Roboto").setFontSize(9);
    ws.getRange(r, 1, 1, 3).setHorizontalAlignment("center");
    ws.getRange(r, 4).setHorizontalAlignment("left");
    ws.getRange(r, 5).setHorizontalAlignment("center"); // Ca làm việc: C1, C1+2, C3, CN
    ws.getRange(r, 6, 1, 9).setHorizontalAlignment("right").setNumberFormat("#,##0.00");
    ws.getRange(r, 15).setHorizontalAlignment("right").setNumberFormat("#,##0.00");
    ws.getRange(r, 16).setHorizontalAlignment("right").setNumberFormat("#,##0"); // Phụ cấp
    ws.getRange(r, 17).setHorizontalAlignment("right").setNumberFormat("#,##0.00");
    ws.getRange(r, 18).setHorizontalAlignment("left");
    ws.getRange(r, 19, 1, 2).setHorizontalAlignment("center");
    ws.getRange(r, 21).setHorizontalAlignment("left");
    ws.getRange(r, 22, 1, 3).setHorizontalAlignment("center");
  }

  SpreadsheetApp.flush();
  SpreadsheetApp.getUi().alert("✅ ĐÃ CẬP NHẬT THÀNH CÔNG!\n\n- Toàn bộ cột Ca đã chuyển thành Ca chuẩn: C1, C1+2, C3, CN (đã xóa sạch mã máy).\n- Tăng ca ngày thường đúng 2 tiếng (không còn số 4).\n- Tổng hợp 13 công nhân tháng 9: 128 công, 150h TC x1.5, 191h TC x2, 2.175.000 đ ăn ca.");
}


